-- Existing module entitlements stay disabled until the vertical's DB/RLS/Gate is ready.
-- The permission catalogue alone must never authorize a non-existent domain.

CREATE FUNCTION app.provision_membership(
 p_user_id uuid,
 p_full_name text,
 p_role_code text,
 p_org_unit_id uuid DEFAULT NULL,
 p_scopes jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
 v_actor uuid := auth.uid();
 v_tenant uuid;
 v_membership public.memberships%ROWTYPE;
BEGIN
 IF v_actor IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='28000'; END IF;
 SELECT id INTO STRICT v_tenant FROM public.tenants;
 IF NOT pvh_private.has_permission(v_tenant,'m00:membership:manage') THEN
   RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
 END IF;
 -- Serialize administrator operations to prevent a concurrent last-admin race.
 PERFORM 1 FROM public.tenants WHERE id=v_tenant FOR UPDATE;
 IF p_user_id IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user_id) THEN
   RAISE EXCEPTION 'UNKNOWN_AUTH_ACCOUNT' USING ERRCODE='22023';
 END IF;
 IF p_full_name IS NULL OR length(btrim(p_full_name)) NOT BETWEEN 1 AND 150 THEN
   RAISE EXCEPTION 'INVALID_FULL_NAME' USING ERRCODE='22023';
 END IF;
 IF p_role_code IS NULL OR NOT EXISTS(SELECT 1 FROM public.roles WHERE code=p_role_code) THEN
   RAISE EXCEPTION 'UNKNOWN_ROLE' USING ERRCODE='22023';
 END IF;
 IF p_scopes IS NULL OR jsonb_typeof(p_scopes)<>'object' THEN
   RAISE EXCEPTION 'INVALID_SCOPE' USING ERRCODE='22023';
 END IF;
 IF p_scopes ? 'org_unit_ids' THEN
   IF jsonb_typeof(p_scopes->'org_unit_ids')<>'array' OR EXISTS(
     SELECT 1 FROM jsonb_array_elements_text(p_scopes->'org_unit_ids') AS elem(value)
     WHERE NOT EXISTS(
       SELECT 1 FROM public.org_units o
       WHERE o.id=elem.value::uuid AND o.tenant_id=v_tenant AND o.is_active
     )
   ) THEN RAISE EXCEPTION 'INVALID_SCOPE_UNITS' USING ERRCODE='22023'; END IF;
 END IF;
 IF p_org_unit_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.org_units WHERE tenant_id=v_tenant AND id=p_org_unit_id AND is_active
 ) THEN RAISE EXCEPTION 'UNKNOWN_ORG_UNIT' USING ERRCODE='22023'; END IF;

 INSERT INTO public.profiles(id,tenant_id,full_name)
 VALUES(p_user_id,v_tenant,btrim(p_full_name))
 ON CONFLICT(id) DO UPDATE SET full_name=excluded.full_name,updated_at=now(),version=profiles.version+1
 WHERE profiles.tenant_id=excluded.tenant_id;

 INSERT INTO public.memberships(tenant_id,user_id,org_unit_id,scopes,created_by,updated_by)
 VALUES(v_tenant,p_user_id,p_org_unit_id,p_scopes,v_actor,v_actor)
 ON CONFLICT(tenant_id,user_id) DO UPDATE SET
   org_unit_id=excluded.org_unit_id,scopes=excluded.scopes,is_active=true,
   valid_from=now(),valid_to=null,updated_at=now(),updated_by=v_actor,
   version=memberships.version+1
 RETURNING * INTO v_membership;

 INSERT INTO public.membership_roles(membership_id,role_code)
 VALUES(v_membership.id,p_role_code) ON CONFLICT DO NOTHING;

 INSERT INTO public.audit_log(tenant_id,actor_id,action,entity_type,entity_id,payload)
 VALUES(v_tenant,v_actor,'PROVISION_MEMBERSHIP','membership',v_membership.id::text,
        jsonb_build_object('targetUserId',p_user_id,'role',p_role_code,'orgUnitId',p_org_unit_id));
 RETURN jsonb_build_object('membershipId',v_membership.id,'tenantId',v_tenant,'userId',p_user_id);
END;
$$;

CREATE FUNCTION app.set_membership_role(p_user_id uuid,p_role_code text,p_grant boolean)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
 v_actor uuid := auth.uid();
 v_tenant uuid;
 v_membership public.memberships%ROWTYPE;
BEGIN
 IF v_actor IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='28000'; END IF;
 SELECT id INTO STRICT v_tenant FROM public.tenants;
 IF NOT pvh_private.has_permission(v_tenant,'m00:membership:manage') THEN
   RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM public.tenants WHERE id=v_tenant FOR UPDATE;
 IF p_grant IS NULL OR p_role_code IS NULL OR NOT EXISTS(SELECT 1 FROM public.roles WHERE code=p_role_code) THEN
   RAISE EXCEPTION 'INVALID_ROLE_CHANGE' USING ERRCODE='22023';
 END IF;
 SELECT * INTO v_membership FROM public.memberships
 WHERE tenant_id=v_tenant AND user_id=p_user_id AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'MEMBERSHIP_NOT_FOUND' USING ERRCODE='P0002'; END IF;

 IF NOT p_grant AND p_role_code='SYSTEM_ADMIN' THEN
   IF p_user_id=v_actor THEN RAISE EXCEPTION 'CANNOT_REVOKE_SELF_ADMIN' USING ERRCODE='42501'; END IF;
   IF (SELECT count(*) FROM public.memberships m JOIN public.membership_roles mr ON mr.membership_id=m.id
       WHERE m.tenant_id=v_tenant AND m.is_active AND mr.role_code='SYSTEM_ADMIN')<=1 THEN
     RAISE EXCEPTION 'CANNOT_REVOKE_LAST_ADMIN' USING ERRCODE='42501';
   END IF;
 END IF;
 IF p_grant THEN
   INSERT INTO public.membership_roles(membership_id,role_code)
   VALUES(v_membership.id,p_role_code) ON CONFLICT DO NOTHING;
 ELSE
   DELETE FROM public.membership_roles WHERE membership_id=v_membership.id AND role_code=p_role_code;
 END IF;
 INSERT INTO public.audit_log(tenant_id,actor_id,action,entity_type,entity_id,payload)
 VALUES(v_tenant,v_actor,'SET_MEMBERSHIP_ROLE','membership',v_membership.id::text,
        jsonb_build_object('role',p_role_code,'granted',p_grant,'targetUserId',p_user_id));
 RETURN jsonb_build_object('membershipId',v_membership.id,'role',p_role_code,'granted',p_grant);
END;
$$;

CREATE FUNCTION app.revoke_membership(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
 v_actor uuid := auth.uid();
 v_tenant uuid;
 v_membership public.memberships%ROWTYPE;
BEGIN
 IF v_actor IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE='28000'; END IF;
 SELECT id INTO STRICT v_tenant FROM public.tenants;
 IF NOT pvh_private.has_permission(v_tenant,'m00:membership:manage') THEN
   RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM public.tenants WHERE id=v_tenant FOR UPDATE;
 IF p_user_id=v_actor THEN RAISE EXCEPTION 'CANNOT_REVOKE_SELF' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_membership FROM public.memberships
 WHERE tenant_id=v_tenant AND user_id=p_user_id AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'MEMBERSHIP_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF EXISTS(SELECT 1 FROM public.membership_roles WHERE membership_id=v_membership.id AND role_code='SYSTEM_ADMIN') AND
   (SELECT count(*) FROM public.memberships m JOIN public.membership_roles mr ON mr.membership_id=m.id
    WHERE m.tenant_id=v_tenant AND m.is_active AND mr.role_code='SYSTEM_ADMIN')<=1 THEN
   RAISE EXCEPTION 'CANNOT_REVOKE_LAST_ADMIN' USING ERRCODE='42501';
 END IF;

 UPDATE public.memberships SET is_active=false,updated_at=now(),updated_by=v_actor,version=version+1
 WHERE id=v_membership.id;
 INSERT INTO public.audit_log(tenant_id,actor_id,action,entity_type,entity_id,payload)
 VALUES(v_tenant,v_actor,'REVOKE_MEMBERSHIP','membership',v_membership.id::text,
        jsonb_build_object('targetUserId',p_user_id));
 RETURN jsonb_build_object('membershipId',v_membership.id,'revoked',true);
END;
$$;

REVOKE ALL ON FUNCTION app.provision_membership(uuid,text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION app.set_membership_role(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION app.revoke_membership(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION app.provision_membership(uuid,text,text,uuid,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION app.set_membership_role(uuid,text,boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION app.revoke_membership(uuid) TO authenticated;
NOTIFY pgrst,'reload schema';
